  "ans": "(1) \\(\\bar{x}=10,\\ \\bar{y}=10.3,\\ S_1^2=0.036,\\ S_2^2=0.04\\)；(2) 新设备生产产品的该项指标的均值较旧设备有显著提高。",
  "sol": "(1) \\(\\bar{x}=\\dfrac{9.8+10.3+10+10.2+9.9+9.8+10+10.1+10.2+9.7}{10}=10\\)；\\(\\bar{y}=\\dfrac{10.1+10.4+10.1+10+10.1+10.3+10.6+10.5+10.4+10.5}{10}=10.3\\)；\\(S_1^2=0.036\\)；\\(S_2^2=0.04\\)。(2) \\(\\bar{y}-\\bar{x}=0.3\\)，\\(2\\sqrt{\\dfrac{0.036+0.04}{10}}=2\\sqrt{0.0076}\\)，因 \\(\\bar{y}-\\bar{x}\\geq 2\\sqrt{\\dfrac{S_1^2+S_2^2}{10}}\\)，故新设备有显著提高。"
