  "sol": "(1) 构建 \\(F(x)=x-\\sin x\\)，\\(x\\in(0,1)\\)，\\(F'(x)=1-\\cos x>0\\)，\\(F(x)\\) 单调递增，\\(F(x)>F(0)=0\\)，所以 \\(x>\\sin x\\)。构建 \\(G(x)=\\sin x-(x-x^{2})=x^{2}-x+\\sin x\\)，\\(G'(x)=2x-1+\\cos x\\)，\\(g(x)=G'(x)\\)，\\(g'(x)=2-\\sin x>0\\)，\\(g(x)\\) 单调递增，\\(g(x)>g(0)=0\\)，\\(G(x)\\) 单调递增，\\(G(x)>G(0)=0\\)，所以 \\(\\sin x>x-x^{2}\\)。综上 \\(x-x^{2}<\\sin x<x\\)。\n(2) 令 \\(1-x^{2}>0\\)，定义域为 \\((-1,1)\\)。\\(f(x)\\) 为偶函数，只需研究 \\((0,1)\\)。\\(f'(x)=-b\\sin bx-\\frac{2x}{x^{2}-1}\\)，\\(b=|a|\\)。当 \\(0<b^{2}\\leqslant2\\) 时，\\(f'(x)>0\\) 在 \\((0,m)\\) 上成立，\\(x=0\\) 是极小值点，不合题意。当 \\(b^{2}>2\\) 时，存在 \\(n\\in(0,\\frac{1}{b})\\) 使 \\(f'(x)<0\\) 在 \\((0,n)\\) 上成立，\\(x=0\\) 是极大值点，符合题意。故 \\(a^{2}>2\\)，\\(a\\) 的取值范围为 \\((-\\infty,-\\sqrt{2})\\cup(\\sqrt{2},+\\infty)\\)。"
