  "stem": "已知函数 \\(f(x)=ax-\\dfrac{\\sin x}{\\cos^{2}x}\\)，\\(x\\in\\left(0,\\dfrac{\\pi}{2}\\right)\\)。（1）当 \\(a=1\\) 时，讨论 \\(f(x)\\) 的单调性；（2）若 \\(f(x)+\\sin x<0\\)，求 \\(a\\) 的取值范围。",
