  "sol": "\\(|OA|=1\\)，\\(|OP|=\\sqrt{2}\\)，\\(\\angle APO=45^{\\circ}\\)，\\(PA=1\\)。设 \\(\\angle OPC=\\alpha\\)（\\(0\\leq\\alpha\\leq\\dfrac{\\pi}{4}\\)）。当 \\(A,D\\) 在 \\(PO\\) 同侧时，\\(\\overrightarrow{PA}\\cdot\\overrightarrow{PD}=\\cos^{2}\\alpha+\\sin\\alpha\\cos\\alpha=\\dfrac{1}{2}+\\dfrac{\\sqrt{2}}{2}\\sin\\left(2\\alpha+\\dfrac{\\pi}{4}\\right)\\)，当 \\(2\\alpha+\\dfrac{\\pi}{4}=\\dfrac{\\pi}{2}\\) 时取最大值 \\(\\dfrac{1+\\sqrt{2}}{2}\\)；异侧时最大值为 \\(1\\)。综上最大值为 \\(\\dfrac{1+\\sqrt{2}}{2}\\)。故选：A。"
