  "diff": "未知",
  "stem": "已知 \\(\\{a_{n}\\}\\) 为等比数列，\\(a_{2}a_{4}a_{5}=a_{3}a_{6}\\)，\\(a_{9}a_{10}=-8\\)，则 \\(a_{7}=\\)___。",
